using Godot;
using System;
using System.Linq;
using System.Collections.Generic;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class DestructionAuthoringOperations
{
    public string source_signature(RefCounted controller,Resource actor){var states=controller.Get("states").AsGodotDictionary();if(!states.TryGetValue(actor.Get("id"),out var state))return "";var source=controller.Get("destruction").AsGodotObject().Call("source",controller,actor.Get("id"),state).AsGodotDictionary();var mesh=Get(source,"mesh").As<Resource>();if(!ActorDataOperations.ScriptIs(mesh,"res://Workspaces/ModelWorkspace/model_mesh.gd"))return "";var points=new GArray();foreach(var point in mesh.Get("vertices").AsVector3Array())points.Add((Vector3I)(point*100000).Round());return ((long)GD.Hash(new GArray{points,mesh.Get("faces")})).ToString(System.Globalization.CultureInfo.InvariantCulture);}
    public Resource capture_setup(RefCounted controller,Resource actor){var setup=_definitions.create_object(definition());var values=Values(setup);values[new StringName("name")]=actor.Get("display_name").AsString()+" destruction";values[new StringName("source_signature")]=source_signature(controller,actor);var settings=new Settings();foreach(string key in SetupFields)settings[new StringName(key)]=_data.copy_value(Get(Values(actor),key));values[new StringName("settings")]=settings;var tracks=actor.Get("animation_tracks").AsGodotArray().Duplicate();tracks.Clear();foreach(var item in actor.Get("animation_tracks").AsGodotArray()){var track=item.As<Resource>();var path=track.Get("path").AsStringArray();if(path.Length>0&&(SetupFields.Contains(path[0])||path[0]=="destruction_enabled"))tracks.Add(_tracks.copy_track(track));}values[new StringName("tracks")]=tracks;return setup;}
    public string apply_setup(RefCounted model,RefCounted controller,Resource actor,Resource? setup){if(setup==null||setup.Get("type_id").AsString()!="destruction_setup")return "Load a Destruction Setup resource first.";string identity=source_signature(controller,actor);if(identity.Length==0||identity!=_data.object_get_value(setup,"source_signature","").AsString())return "Source topology differs. Apply this setup to a matching mesh; no vertex or fragment data was copied.";var before=_data.copy_value(actor.Get("values")).AsGodotDictionary();var after=_data.copy_value(actor.Get("values")).AsGodotDictionary();after.Merge(_data.copy_value(_data.object_get_value(setup,"settings",new Settings())).AsGodotDictionary(),true);after[new StringName("destruction_enabled")]=true;var oldTracks=model.Call("animation_snapshot",actor).AsGodotArray();var tracks=oldTracks.Duplicate();tracks.Clear();foreach(var item in oldTracks){var track=item.As<Resource>();var path=track.Get("path").AsStringArray();if(path.Length==0||!SetupFields.Contains(path[0])&&path[0]!="destruction_enabled")tracks.Add(_tracks.copy_track(track));}foreach(var item in _data.object_get_value(setup,"tracks",new GArray()).AsGodotArray())tracks.Add(_tracks.copy_track(item.As<Resource>()));History(model,actor,"Apply destruction setup",new StringName(""),before,after,oldTracks,tracks,true);return "";}
    public void assign_setup(WeakRef reference,Resource actor,Settings values,GArray tracks){using var target=reference.GetRef();if(target.AsGodotObject() is not RefCounted model)return;actor.Set("values",_data.copy_value(values));actor.Get("animation_previews").AsGodotDictionary().Clear();model.Call("restore_animation",actor,tracks);}
    public void assign_values(WeakRef reference,Resource actor,Settings values){using var target=reference.GetRef();if(target.AsGodotObject() is not RefCounted model)return;actor.Set("values",_data.copy_value(values));actor.EmitChanged();model.EmitSignal("changed");}
    private Settings FragmentRule(StringName field)=>field.ToString()=="destruction_fragments"?fragment_defaults(Vector3.Zero):new Settings{["enabled"]=true,["offset"]=Vector3.Zero,["rotation"]=Vector3.Zero};
    private void WriteKey(Resource track,double time,Variant value){var frame=_tracks.key_at(track,time);if(frame==null){frame=new ActorKeyframe();frame.Set("id",_data.new_id());frame.Set("time",time);track.Get("keys").AsGodotArray().Add(frame);}int component=track.Get("component").AsInt32();frame.Set("value",_data.copy_value(component>=0?ActorAnimationOperations.Component(value,component):value));_tracks.sort_keys(track);}
    public void edit_fragments(RefCounted model,Resource actor,StringName field,GArray ids,string key,Variant value)
    {
        if(ids.Count==0)return;bool guided=key=="guided_target";if(guided)key="target";var before=_data.copy_value(Get(Values(actor),field.ToString(),new Settings())).AsGodotDictionary();var next=before.Duplicate(true);var tracks=model.Call("animation_snapshot",actor).AsGodotArray();var after=model.Call("animation_snapshot",actor).AsGodotArray();var clip=model.Call("clip_for_actor_id",actor.Get("id")).As<Resource>();foreach(var idValue in ids){string id=idValue.AsString();if(!next.ContainsKey(id))next[id]=FragmentRule(field);if(guided)next[id].AsGodotDictionary()["mode"]=1;var path=new[]{field.ToString(),id,key};bool found=false;foreach(var item in after){var track=item.As<Resource>();if(!track.Get("path").AsStringArray().SequenceEqual(path))continue;found=true;WriteKey(track,_runtime.local_time(clip,model.Get("playhead_time").AsDouble()),value);}if(!found)next[id].AsGodotDictionary()[key]=_data.copy_value(value);}History(model,actor,field.ToString()=="growth_overrides"?"Correct growth motion":field.ToString()=="destruction_fragments"?"Direct fragments":"Correct fragment animation",field,before,next,tracks,after);
    }
    public void restore_fragments(WeakRef reference,Resource actor,StringName field,Settings values,GArray tracks){using var target=reference.GetRef();if(target.AsGodotObject() is not RefCounted model)return;Values(actor)[field]=_data.copy_value(values);actor.Get("animation_previews").AsGodotDictionary().Clear();model.Call("restore_animation",actor,tracks);}
    public void key_fragments(RefCounted model,Resource actor,StringName field,GArray ids,string key,Variant fallback)
    {
        if(ids.Count==0)return;var before=_data.copy_value(_data.get_value(actor,field,new Settings())).AsGodotDictionary();var next=before.Duplicate(true);var tracks=model.Call("animation_snapshot",actor).AsGodotArray();var after=model.Call("animation_snapshot",actor).AsGodotArray();foreach(var idValue in ids){string id=idValue.AsString();if(!next.ContainsKey(id))next[id]=FragmentRule(field);var path=new[]{field.ToString(),id,key};var matches=new List<Resource>();foreach(var item in after){var candidate=item.As<Resource>();if(candidate.Get("path").AsStringArray().SequenceEqual(path))matches.Add(candidate);}if(matches.Count==0){var track=new ActorAnimationTrack();track.Set("path",path);string prefix=id.Split(':')[0]+":";track.Set("label",(field.ToString()=="destruction_overrides"?"Correction ":"Piece ")+(id.StartsWith(prefix,StringComparison.Ordinal)?id.Substring(prefix.Length):id)+" · "+key.Replace("_"," ").Capitalize());after.Add(track);matches.Add(track);}var clip=model.Call("clip_for_actor_id",actor.Get("id")).As<Resource>();double time=_runtime.local_time(clip,model.Get("playhead_time").AsDouble());var value=_animation.sampled_value(actor,path,time,Get(next[id].AsGodotDictionary(),key,fallback));foreach(var track in matches)WriteKey(track,time,value);}History(model,actor,"Keyframe selected fragments",field,before,next,tracks,after);model.Set("overlay_actor_id",actor.Get("id"));model.Set("overlay_path",new[]{field.ToString(),ids[0].AsString(),key});model.EmitSignal("changed");
    }
}
